    var changed=new ArrayList<FullRow>();for(var row:rows){if(convert&&Set.of(Table.ACTION_ITEM,Table.ACTION_SUGGESTION).contains(row.table())&&element.equals(row.string("element_id")))continue;var cells=new ArrayList<>(row.cells());if(row.table()==Table.MINUTES_ELEMENT&&element.equals(row.string("id"))){if(fields==null)cells.set(row.table().index("body"),cell(body));if(convert)cells.set(row.table().index("category"),cell("OPEN_QUESTION"));}else if(row.table()==Table.ACTION_ITEM&&element.equals(row.string("element_id"))&&fields!=null){cells.set(row.table().index("owner_enterprise_id"),nullable(fields.ownerEnterpriseId()));cells.set(row.table().index("owner_display"),nullable(fields.ownerDisplay()));cells.set(row.table().index("due_on"),nullable(fields.dueOn()));}else if(row.table()==Table.EVIDENCE_LINK&&element.equals(row.nullableString("element_id"))&&fields==null){var anchor=map.get(row.string("id"));cells.set(row.table().index("target_anchor"),cell(ama.minutes.contract.OutputValidation.anchorText(ama.minutes.contract.OutputValidation.anchor(body,anchor.start(),anchor.end(),()->false))));}changed.add(new FullRow(row.table(),cells));}rows=changed;
    if(convert){var order=new HashMap<String,Long>();for(Category category:Category.values()){var members=rows.stream().filter(row->row.table()==Table.MINUTES_ELEMENT&&source.equals(row.string("set_id"))&&category.name().equals(row.string("category"))).sorted(Comparator.comparing((FullRow row)->element.equals(row.string("id"))).thenComparingLong(row->row.number("ordinal")).thenComparing(row->row.string("id"))).toList();long ordinal=0;for(var member:members)order.put(member.string("id"),++ordinal);}rows=rows.stream().map(row->{if(row.table()!=Table.MINUTES_ELEMENT||!source.equals(row.string("set_id")))return row;var cells=new ArrayList<>(row.cells());cells.set(row.table().index("ordinal"),cell(order.get(row.string("id"))));return new FullRow(row.table(),cells);}).collect(java.util.stream.Collectors.toCollection(ArrayList::new));}
